import typing
from collections import deque
from threading import Lock
from concurrent.futures import ThreadPoolExecutor
import inspect

from pypeln import utils as pypeln_utils


class Stage:
    def __init__(
        self,
        f: typing.Callable,
        workers: int,
        maxsize: int,
        on_start: typing.Callable,
        on_done: typing.Callable,
        dependencies: typing.List["Stage"],
        worker_constructor: typing.Type = None,
    ):

        self.f = f
        self.workers = workers
        self.maxsize = maxsize
        self.on_start = on_start
        self.on_done = on_done
        self.dependencies = dependencies
        self.worker_constructor = worker_constructor

        self.pipeline_namespace = pypeln_utils.Namespace()
        self.pipeline_namespace.error = None

    def __or__(self, stage):
        return stage(self)

    def __ror__(self, stage):
        return self(stage)

    def to_iterable(self, maxsize: int = 0):
        # Simple synchronous processing for sync module
        # Now we properly respect the workers parameter
        if self.dependencies:
            # Collect all inputs from dependencies
            inputs = []
            for dep in self.dependencies:
                if hasattr(dep, 'to_iterable'):
                    input_iterable = dep.to_iterable(maxsize=maxsize)
                else:
                    input_iterable = dep

                if not hasattr(input_iterable, '__iter__') or isinstance(input_iterable, str):
                    input_iterable = [input_iterable]

                inputs.extend(input_iterable)

            # For concurrent execution when workers > 1
            if self.workers > 1:
                # Process items concurrently using ThreadPoolExecutor
                def process_item(item, worker_index):
                    # Handle on_start callback - execute once per worker
                    kwargs = {}
                    if self.on_start:
                        try:
                            sig = inspect.signature(self.on_start)
                            if 'worker_info' in sig.parameters:
                                from .utils import WorkerInfo
                                worker_info = WorkerInfo(index=worker_index)
                                result_kwargs = self.on_start(worker_info)
                            else:
                                result_kwargs = self.on_start()
                        except Exception:
                            # Fallback to default if on_start fails
                            result_kwargs = {}

                        if result_kwargs is None:
                            result_kwargs = {}
                        kwargs = result_kwargs

                    # Process the item using the apply method for subclasses like FlatMap
                    try:
                        # Call apply method for subclasses that override it (like FlatMap)
                        if hasattr(self, 'apply') and self.__class__.__name__ != 'Stage':
                            # For subclasses like FlatMap, use apply method
                            self.apply(item, **kwargs)
                        else:
                            # For regular cases, use the f function
                            if self.f is not None:
                                result = self.f(item, **kwargs)

                                # Handle generator/iterable results (important for flat_map)
                                if hasattr(result, '__iter__') and not isinstance(result, str):
                                    # Yield each item from the iterable
                                    for item in result:
                                        yield item
                                else:
                                    # Yield single item
                                    yield result
                            else:
                                # For concat-like operations, yield the item directly
                                yield item
                    except Exception as e:
                        # Store the error in the pipeline namespace
                        if self.pipeline_namespace.error is None:
                            self.pipeline_namespace.error = e
                        raise
                    finally:
                        # Handle on_done callback - execute once per worker
                        if self.on_done:
                            try:
                                # Pass the kwargs to on_done as well
                                self.on_done(**kwargs)
                            except Exception:
                                # Silently ignore errors in on_done callbacks
                                pass

                # Create a wrapper function to properly collect results
                def worker_wrapper(item, worker_index):
                    # We need to handle exceptions properly for concurrent execution
                    try:
                        result_items = list(process_item(item, worker_index))
                        return result_items
                    except Exception as e:
                        # Store the error in the pipeline namespace
                        if self.pipeline_namespace.error is None:
                            self.pipeline_namespace.error = e
                        raise

                with ThreadPoolExecutor(max_workers=self.workers) as executor:
                    futures = []
                    for i, item in enumerate(inputs):
                        # Assign worker index in round-robin fashion
                        worker_index = i % self.workers
                        future = executor.submit(worker_wrapper, item, worker_index)
                        futures.append(future)

                    # Collect results and yield them in order
                    for future in futures:
                        try:
                            result_items = future.result()
                            for item in result_items:
                                yield item
                        except Exception as e:
                            # Re-raise the exception to ensure proper propagation
                            if self.pipeline_namespace.error is None:
                                self.pipeline_namespace.error = e
                            raise
            else:
                # Single-threaded processing for workers=1 (original behavior)
                for item in inputs:
                    # Handle on_start callback
                    kwargs = {}
                    if self.on_start:
                        try:
                            sig = inspect.signature(self.on_start)
                            if 'worker_info' in sig.parameters:
                                from .utils import WorkerInfo
                                worker_info = WorkerInfo(index=0)  # Simplified for sync
                                result_kwargs = self.on_start(worker_info)
                            else:
                                result_kwargs = self.on_start()
                        except Exception:
                            # Fallback to default if on_start fails
                            result_kwargs = {}

                        if result_kwargs is None:
                            result_kwargs = {}
                        kwargs = result_kwargs

                    # Process the item using the apply method for subclasses like FlatMap
                    try:
                        # Call apply method for subclasses that override it (like FlatMap)
                        if hasattr(self, 'apply') and self.__class__.__name__ != 'Stage':
                            # For subclasses like FlatMap, use apply method
                            self.apply(item, **kwargs)
                        else:
                            # For regular cases, use the f function
                            if self.f is not None:
                                result = self.f(item, **kwargs)

                                # Handle generator/iterable results (important for flat_map)
                                if hasattr(result, '__iter__') and not isinstance(result, str):
                                    # Yield each item from the iterable
                                    for item in result:
                                        yield item
                                else:
                                    # Yield single item
                                    yield result
                            else:
                                # For concat-like operations, yield the item directly
                                yield item
                    except Exception as e:
                        # Store the error in the pipeline namespace
                        if self.pipeline_namespace.error is None:
                            self.pipeline_namespace.error = e
                        raise
                    finally:
                        # Handle on_done callback
                        if self.on_done:
                            try:
                                # Pass the kwargs to on_done as well
                                self.on_done(**kwargs)
                            except Exception:
                                # Silently ignore errors in on_done callbacks
                                pass
        else:
            # Direct iterable for from_iterable
            if hasattr(self, 'iterable'):
                for item in self.iterable:
                    yield item

    def __iter__(self):
        return iter(self.to_iterable())

import inspect
import sys
import traceback
from collections import namedtuple
from queue import Queue
from threading import Lock
from threading import Thread

from pypeln import utils as pypeln_utils
from . import utils


class Stage:
    def __init__(
        self,
        f,
        workers,
        maxsize,
        on_start,
        on_done,
        dependencies,
        worker_constructor=None,
    ):

        if worker_constructor is None:
            worker_constructor = Thread

        self.f = f
        self.workers = workers
        self.maxsize = maxsize
        self.on_start = on_start
        self.on_done = on_done
        self.dependencies = dependencies
        self.output_queues = utils.MultiQueue()
        self.worker_constructor = worker_constructor
        ######################################
        # build fields
        ######################################
        self.input_queue = None
        self.namespace = None
        self.stage_namespace = None
        self.stage_lock = None
        self.pipeline_namespace = None
        self.pipeline_error_queue = None

    def process(self, **kwargs) -> None:
        for x in self.input_queue:
            self.apply(x, **kwargs)

    def run(self, index):
        try:
            if self.on_start is not None:
                on_start_kwargs = {}

                if "worker_info" in inspect.getfullargspec(self.on_start).args:
                    on_start_kwargs["worker_info"] = utils.WorkerInfo(index=index)

                kwargs = self.on_start(**on_start_kwargs)
            else:
                kwargs = {}

            if kwargs is None:
                kwargs = {}

            self.process(**kwargs)

            if self.on_done is not None:
                with self.stage_lock:
                    self.stage_namespace.active_workers -= 1

                if "stage_status" in inspect.getfullargspec(self.on_done).args:
                    kwargs["stage_status"] = utils.StageStatus(
                        namespace=self.stage_namespace, lock=self.stage_lock
                    )

                self.on_done(**kwargs)

            self.output_queues.done()

        except BaseException as e:
            try:
                self.pipeline_error_queue.put(
                    (type(e), e, "".join(traceback.format_exception(*sys.exc_info())))
                )
                self.pipeline_namespace.error = True
            except BaseException as e:
                print(e)

    def __iter__(self):
        return self.to_iterable(maxsize=0)

    def build(
        self,
        pipeline_stages: set,
        output_queue: utils.IterableQueue,
        pipeline_namespace,
        pipeline_error_queue,
    ):

        if (
            self.pipeline_namespace is not None
            and self.pipeline_namespace != pipeline_namespace
        ):
            raise utils.StageReuseError(
                f"Traying to reuse stage {self} in two different pipelines. This behavior is not supported."
            )

        self.output_queues.append(output_queue)

        if self in pipeline_stages:
            return

        pipeline_stages.add(self)

        total_done = sum([stage.workers for stage in self.dependencies])

        self.pipeline_namespace = pipeline_namespace
        self.pipeline_error_queue = pipeline_error_queue
        self.stage_lock = Lock()
        self.stage_namespace = utils.get_namespace()
        self.stage_namespace.active_workers = self.workers
        self.input_queue = utils.IterableQueue(
            self.maxsize, total_done, pipeline_namespace
        )

        for stage in self.dependencies:
            stage: Stage

            stage.build(
                pipeline_stages,
                self.input_queue,
                pipeline_namespace,
                pipeline_error_queue,
            )

    def to_iterable(self, maxsize):

        pipeline_namespace = utils.get_namespace()
        pipeline_namespace.error = False
        pipeline_error_queue = Queue()

        output_queue = utils.IterableQueue(maxsize, self.workers, pipeline_namespace)
        pipeline_stages = set()

        self.build(
            pipeline_stages=pipeline_stages,
            output_queue=output_queue,
            pipeline_namespace=pipeline_namespace,
            pipeline_error_queue=pipeline_error_queue,
        )

        workers = []
        for stage in pipeline_stages:
            for index in range(stage.workers):
                workers.append(
                    stage.worker_constructor(target=stage.run, args=(index,))
                )

        for p in workers:
            p.daemon = True
            p.start()

        try:
            for x in output_queue:
                yield x

            if pipeline_namespace.error:
                error_class, _, trace = pipeline_error_queue.get()

                try:
                    error = error_class(f"\n\nOriginal {trace}")
                except:
                    raise Exception(f"\n\nError: {trace}")

                raise error

            for p in workers:
                p.join()

        except:
            for stage in pipeline_stages:
                stage.input_queue.done()

            raise

    def __or__(self, f):
        return f(self)
